"""Generated effect providers. CONTENT ASSERTION IS THE DEFAULT.

Two providers per semantic effect port, and shipping two is the point:
the checking one is bound by the generated default mapping, and the
silent one exists so that choosing it is a VISIBLE edit to a mapping
file rather than an assertion somebody quietly did not write.

Neither suppresses anything. There is no flag that turns the checking
provider's assertions off -- a suppression key would have been the
shorter route and the wrong one, because a reader of a kill number has
to be able to see which instrument produced it.

Nothing here refuses to run. Every degraded configuration is announced
on stdout the first time it binds, and the run proceeds.
"""

from __future__ import annotations

import dataclasses
import os
import sys
from contextlib import contextmanager
from collections.abc import Iterator
from typing import Any

from .types import ReminderState, ReadClock, ClaimJob, LookupOutbox, StageMessage, SendMessage, MarkSent, QueueMutation


NO_ORACLE_SENTENCE = 'Nothing compares what crossed this port against the model, so kills counted under this mapping are a FLOOR, not a total, and a green run over-reads.'
ANNOUNCE_PREFIX = '[effect-mapping]'

#: port -> method -> payload field -> modeled value it must equal.
CONTENT_ASSERTIONS: dict[str, dict[str, dict[str, str]]] = {
    'ClockPort': {},
    'QueuePort': {},
    'OutboxPort': {},
    'NotifierPort': {},
}

#: port -> declared boundary kind, from `ports:` or `effects:`.
PORT_KINDS: dict[str, str] = {
    'ClockPort': 'effect',
    'QueuePort': 'effect',
    'OutboxPort': 'effect',
    'NotifierPort': 'effect',
}

#: Boundaries declared under `effects:` that no provider can be bound to.
#: They are reported, never repaired -- a declaration without a seam is a
#: finding for the project, not something codegen may invent a port for.
UNBOUND_DECLARED_BOUNDARIES: dict[str, str] = {}


@dataclasses.dataclass(frozen=True)
class EffectCrossing:
    port: str
    method: str
    payload: dict


def _payload(command: Any) -> dict:
    if dataclasses.is_dataclass(command):
        return {field.name: getattr(command, field.name) for field in dataclasses.fields(command)}
    if isinstance(command, dict):
        return dict(command)
    return {'value': command}


def _reference(provider: Any) -> str:
    return f'{type(provider).__module__}:{type(provider).__name__}'


def mapping_name() -> str:
    """Which mapping produced these numbers.

    The framework does not hand a provider its mapping path, so this reads
    the run's own invocation. It is a hint, not a contract, and it says so
    when it cannot tell -- an unnamed mapping is itself worth announcing.
    """
    named = os.environ.get('TLA_SPEC_DEV_MAPPING')
    if named:
        return named
    argv = list(sys.argv)
    for index, token in enumerate(argv):
        if token == '--mapping' and index + 1 < len(argv):
            return argv[index + 1]
        if token.startswith('--mapping='):
            return token.split('=', 1)[1]
    return '<unnamed mapping: set TLA_SPEC_DEV_MAPPING to name it>'


_ANNOUNCED: set = set()


def announce_binding(port: str, reference: str, *, asserts_content: bool) -> None:
    """Say which instrument this is, once per port per process, unprompted."""
    mapping = mapping_name()
    key = (port, reference, mapping, asserts_content)
    if key in _ANNOUNCED:
        return
    _ANNOUNCED.add(key)
    for line in describe_binding(port, reference, mapping, asserts_content=asserts_content):
        print(line, flush=True)


def describe_binding(port: str, reference: str, mapping: str, *, asserts_content: bool) -> list[str]:
    kind = PORT_KINDS.get(port, 'effect')
    fields = sorted(
        f'{method}.{field} == {expression}'
        for method, spec in CONTENT_ASSERTIONS.get(port, {}).items()
        for field, expression in spec.items()
    )
    if asserts_content and fields:
        return [
            f'{ANNOUNCE_PREFIX} DURABLE-WRITE ORACLE ACTIVE: {port} (kind: {kind}) is bound to '
            f'{reference} under mapping {mapping}, asserting ' + str(len(fields)) + ' content field(s) '
            f'against the modeled after-state: ' + '; '.join(fields),
        ]
    if asserts_content:
        return [
            f'{ANNOUNCE_PREFIX} NO DURABLE-WRITE ORACLE: {port} (kind: {kind}) is bound to '
            f'{reference} under mapping {mapping}, which records every crossing but declares no '
            f'`content:` block, so no payload field is compared to anything. ' + NO_ORACLE_SENTENCE,
        ]
    return [
        f'{ANNOUNCE_PREFIX} NO DURABLE-WRITE ORACLE: {port} (kind: {kind}) is bound to the SILENT '
        f'provider {reference} under mapping {mapping}. ' + NO_ORACLE_SENTENCE,
    ]


def _after(case: Any) -> Any:
    after = getattr(case, 'after', None)
    return {} if after is None else after


def _lookup(container: Any, key: Any) -> Any:
    try:
        return container[key]
    except (TypeError, KeyError, IndexError):
        return getattr(container, str(key))


def resolve(expression: str, after: Any, payload: dict) -> Any:
    """`variable` or `variable[payload_field]`, evaluated against the after-state."""
    name, bracket, rest = expression.partition('[')
    value = _lookup(after, name.strip())
    if bracket:
        field = rest.rstrip(']').strip()
        if field not in payload:
            raise AssertionError(
                f'content assertion {expression!r} indexes by payload field {field!r}, '
                f'which this crossing does not carry: {sorted(payload)}'
            )
        value = _lookup(value, payload[field])
    return value


def assert_content(port: str, crossings: list, context: Any) -> None:
    """Compare what crossed the boundary with what the model says is true after.

    A durable write is the one thing an after-state comparison structurally
    cannot see: the in-memory projection can be perfect while the persisted
    bytes are wrong. This is the check that sees it.
    """
    spec = CONTENT_ASSERTIONS.get(port) or {}
    if not spec:
        return
    after = _after(getattr(context, 'case', None))
    for crossing in crossings:
        for field, expression in spec.get(crossing.method, {}).items():
            if field not in crossing.payload:
                raise AssertionError(
                    f'DETECTOR[provider_content_assertion] {port}.{crossing.method} declares a content '
                    f'assertion on {field!r}, which the crossing does not carry: {sorted(crossing.payload)}'
                )
            observed = crossing.payload[field]
            expected = resolve(expression, after, crossing.payload)
            if observed != expected:
                raise AssertionError(
                    f'DETECTOR[provider_content_assertion] {port}.{crossing.method} wrote {field}='
                    f'{observed!r} but the model says {expression} == {expected!r} '
                    f'(action={getattr(context, "action", None)!r}, '
                    f'case={getattr(getattr(context, "case", None), "name", None)!r})'
                )


class RecordingClockPort:
    """The bound ClockPort. Every crossing is recorded so the model can judge it."""

    def __init__(self) -> None:
        self.crossings: list[EffectCrossing] = []

    def now(self, command: ReadClock) -> int:
        self.crossings.append(EffectCrossing('ClockPort', 'now', _payload(command)))
        return 0


class ContentAssertingClockPortProvider:
    """THE DEFAULT for ClockPort. Asserts the payload against the modeled after-state."""

    port_name = 'ClockPort'
    asserts_content = True

    @contextmanager
    def bind(self, context: Any) -> Iterator[Any]:
        binding = RecordingClockPort()
        announce_binding('ClockPort', _reference(self), asserts_content=True)
        yield binding
        assert_content('ClockPort', binding.crossings, context)


